function ExternalPage({ url, label }: { url: string; label: string }) {
  const icons: Record<string, React.ReactNode> = {
    GitHub: <Github />,
    LinkedIn: <Linkedin />,
    LeetCode: <Code2 />,
    "X / Twitter": <Twitter />,
