          {icons[label] ?? <ExternalLink />}
        </div>
        <div className="mt-4 text-lg font-semibold">{label} can't be embedded</div>
        <p className="mt-1 text-sm text-white/60">
          This site blocks in-app previews for security. Open it in your real browser to view it.
        </p>
        <div className="mt-2 break-all text-[11px] text-white/40">{url}</div>
        <button
          onClick={() => window.open(url, "_blank", "noopener,noreferrer")}
          className="mt-5 inline-flex items-center gap-2 rounded-md bg-sky-500 px-4 py-2 text-sm font-medium hover:bg-sky-400"
        >
          <ExternalLink size={14} /> Open in browser
        </button>
      </div>
    </div>
  );
}

export function SafariApp({ win }: { win?: WindowState }) {
  const initial = (win?.payload?.url as string | undefined) ?? START_URL;
  const [history, setHistory] = useState<string[]>([initial]);
  const [index, setIndex] = useState(0);
  const [draft, setDraft] = useState(initial);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  const current = history[index];
  const external = useMemo(() => detectExternalOnly(current), [current]);
  const embedUrl = useMemo(() => toEmbeddable(current), [current]);

  useEffect(() => {
    setDraft(current);
  }, [current]);

  const navigate = (raw: string) => {
    const url = normalizeUrl(raw);
    const next = history.slice(0, index + 1).concat(url);
    setHistory(next);
    setIndex(next.length - 1);
  };

  const back = () => index > 0 && setIndex(index - 1);
  const forward = () => index < history.length - 1 && setIndex(index + 1);
  const reload = () => {
    if (iframeRef.current) iframeRef.current.src = iframeRef.current.src;
  };

  const isStart = current === START_URL;

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center gap-2 border-b border-white/10 bg-black/30 px-3 py-1.5">
        <button onClick={back} disabled={index === 0} className="rounded p-1 hover:bg-white/10 disabled:opacity-30" aria-label="Back">
          <ArrowLeft size={14} />
        </button>
        <button onClick={forward} disabled={index >= history.length - 1} className="rounded p-1 hover:bg-white/10 disabled:opacity-30" aria-label="Forward">
          <ArrowRight size={14} />
        </button>
        <button onClick={reload} className="rounded p-1 hover:bg-white/10" aria-label="Reload">
          <RotateCw size={14} />
        </button>
        <form
          className="mx-2 flex-1"
          onSubmit={(e) => {
            e.preventDefault();
            navigate(draft);
          }}
        >
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            className="w-full rounded-md bg-white/10 px-3 py-1 text-sm text-white outline-none placeholder:text-white/40"
          />
        </form>
      </div>
      <div className="flex-1 overflow-hidden bg-gradient-to-b from-[oklch(0.24_0.02_260)] to-[oklch(0.18_0.02_260)]">
        {isStart ? (
          <div className="h-full overflow-y-auto">
            <StartPage />
          </div>
        ) : external ? (
          <ExternalPage url={current} label={external.label} />
        ) : (
          <iframe
            ref={iframeRef}
            key={embedUrl}
            src={embedUrl}
            title="Safari"
            className="h-full w-full border-0 bg-white"
            sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation allow-top-navigation"
            referrerPolicy="no-referrer"
          />
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { profile, projects, skills, experience, research } from "../data";
import { useWM } from "../WindowManager";

type Line = { kind: "in" | "out"; text: string };

const HELP = [
  "Available commands:",
  "  whoami        — who is Noor",
  "  about         — short bio",
  "  skills        — tech stack",
  "  projects      — list projects",
  "  experience    — work history",
  "  research      — published paper",
  "  contact       — reach out",
  "  resume        — open resume",
  "  open <app>    — about|projects|safari|resume|mail|research",
  "  clear         — clear screen",
  "  help          — this message",
];

export function TerminalApp() {
  const { open } = useWM();
  const [lines, setLines] = useState<Line[]>([
    { kind: "out", text: "Last login: today · noor@macbook-pro" },
    { kind: "out", text: 'Type "help" to see available commands.' },
  ]);
  const [input, setInput] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [lines]);

  function run(cmd: string) {
    const raw = cmd.trim();
    const [c, ...rest] = raw.split(/\s+/);
    const out: string[] = [];
    switch (c) {
      case "":
        break;
      case "help":
        out.push(...HELP);
        break;
      case "whoami":
        out.push("Noor", "Software Engineer", "AI Developer");
        break;
      case "about":
        out.push(profile.tagline);
        break;
      case "skills":
        for (const [g, list] of Object.entries(skills)) out.push(`${g}: ${list.join(", ")}`);
        break;
      case "projects":
        projects.forEach((p) => out.push(`• ${p.name} — ${p.tagline}`));
        out.push("", 'Run "open projects" to explore in Finder.');
        break;
      case "experience":
        experience.forEach((e) => out.push(`${e.role} @ ${e.org}  (${e.period})`));
        break;
      case "research":
        out.push(research.title, `${research.authors.join(", ")} — ${research.venue}`, research.publisher);
        break;
      case "contact":
        out.push(`Email: ${profile.email}`, 'Or run "open mail".');
        break;
      case "resume":
        open("resume");
        out.push("Opening Resume.pdf in Preview…");
        break;
      case "open": {
        const app = rest[0];
        const known = ["about", "projects", "safari", "resume", "mail", "research", "terminal"] as const;
        if (known.includes(app as (typeof known)[number])) {
          open(app as (typeof known)[number]);
          out.push(`Opening ${app}…`);
        } else {
          out.push(`open: unknown app "${app ?? ""}"`);
        }
        break;
      }
      case "clear":
        setLines([]);
        return;
      default:
        out.push(`zsh: command not found: ${c}. Try "help".`);
    }
    setLines((ls) => [
      ...ls,
      { kind: "in", text: raw },
      ...out.map<Line>((t) => ({ kind: "out", text: t })),
    ]);
  }

  return (
    <div
      className="h-full cursor-text bg-black/70 font-mono text-[13px] text-emerald-300"
      onClick={() => inputRef.current?.focus()}
    >
      <div ref={scrollRef} className="h-full overflow-y-auto p-3">
        {lines.map((l, i) =>
          l.kind === "in" ? (
            <div key={i}>
              <span className="text-sky-300">noor@macbook</span>
              <span className="text-white/60"> ~ % </span>
              <span className="text-white">{l.text}</span>
            </div>
          ) : (
            <div key={i} className="whitespace-pre-wrap text-white/85">
              {l.text}
            </div>
          ),
        )}
        <div className="flex">
          <span className="text-sky-300">noor@macbook</span>
          <span className="text-white/60">&nbsp;~&nbsp;%&nbsp;</span>
          <input
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                run(input);
                setInput("");
              }
            }}
            className="flex-1 bg-transparent text-white caret-emerald-300 outline-none"
            spellCheck={false}
            autoFocus
          />
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Play, Pause, Maximize2 } from "lucide-react";
import type { WindowState } from "../types";

export function VideoApp({ win }: { win: WindowState }) {
  const name = (win.payload?.name as string | undefined) ?? "Project Demo";
  const [playing, setPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const intRef = useRef<number | null>(null);

  useEffect(() => {
    if (playing) {
      intRef.current = window.setInterval(() => {
        setProgress((p) => (p >= 100 ? (setPlaying(false), 100) : p + 0.5));
      }, 50);
    }
    return () => {
      if (intRef.current) window.clearInterval(intRef.current);
    };
  }, [playing]);

  return (
    <div className="flex h-full flex-col bg-black text-white">
      <div className="relative flex-1 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-900 via-purple-900 to-black" />
        <div className="relative grid h-full place-items-center">
          <div className="text-center">
            <div className="text-xs uppercase tracking-widest text-white/50">Now Playing</div>
            <div className="mt-1 text-2xl font-semibold">{name}</div>
            <button
              onClick={() => setPlaying((p) => !p)}
              className="mt-6 grid h-16 w-16 place-items-center rounded-full bg-white/15 backdrop-blur transition hover:scale-105"
            >
              {playing ? <Pause size={26} /> : <Play size={26} />}
            </button>
          </div>
        </div>
      </div>
      <div className="flex items-center gap-3 border-t border-white/10 bg-black/60 px-4 py-2 text-xs">
        <button onClick={() => setPlaying((p) => !p)} className="rounded p-1 hover:bg-white/10">
          {playing ? <Pause size={14} /> : <Play size={14} />}
        </button>
        <div className="relative flex-1 h-1 rounded-full bg-white/15">
          <div className="absolute inset-y-0 left-0 rounded-full bg-white/90" style={{ width: `${progress}%` }} />
        </div>
        <span className="tabular-nums text-white/70">
          {Math.floor(progress * 0.6).toString().padStart(2, "0")}:
          {Math.floor(((progress * 0.6) % 1) * 60).toString().padStart(2, "0")} / 01:00
        </span>
        <button className="rounded p-1 hover:bg-white/10">
          <Maximize2 size={14} />
        </button>
      </div>
    </div>
  );
}

