import { motion, useMotionValue, useSpring, useTransform, type MotionValue } from "framer-motion";
import { useRef } from "react";
import {
  FolderKanban,
  Terminal as TerminalIcon,
  Globe,
  FileText,
} from "lucide-react";
import { useWM } from "./WindowManager";
import { profile } from "./data";
import type { AppId } from "./types";

type DockItem = {
  id: AppId;
  label: string;
  icon: React.ReactNode;
  gradient: string;
};

const items: DockItem[] = [
  { id: "projects", label: "Projects", icon: <FolderKanban />, gradient: "from-sky-300 to-blue-500" },
  { id: "terminal", label: "Terminal", icon: <TerminalIcon />, gradient: "from-zinc-700 to-zinc-900" },
  { id: "safari", label: "Safari", icon: <Globe />, gradient: "from-cyan-300 to-blue-500" },
  { id: "resume", label: "Resume", icon: <FileText />, gradient: "from-slate-100 to-slate-300" },
];

export function Dock() {
  const { open, openApps, windows, focus } = useWM();
  const mouseX = useMotionValue<number>(Infinity);

  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-2 z-[9998] flex justify-center">
      <motion.div
        onMouseMove={(e) => mouseX.set(e.clientX)}
        onMouseLeave={() => mouseX.set(Infinity)}
        className="pointer-events-auto flex items-end gap-2 rounded-2xl border border-white/15 bg-white/10 px-3 py-2 backdrop-blur-2xl"
        style={{ boxShadow: "0 20px 40px -20px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.25)" }}
      >
        {items.map((it) => (
          <DockIcon
            key={it.id}
            item={it}
            mouseX={mouseX}
            isOpen={openApps.has(it.id)}
            onClick={() => {
              if (it.id === "resume") {
                open("safari", {
                  title: "Resume — Safari",
                  payload: { url: profile.links.resume },
                });
                return;
              }
              const existing = windows.find((w) => w.appId === it.id);
              if (existing) focus(existing.id);
              else open(it.id);
            }}
          />
        ))}
      </motion.div>
    </div>
  );
}

function DockIcon({
  item,
  mouseX,
  isOpen,
  onClick,
}: {
  item: DockItem;
  mouseX: MotionValue<number>;
  isOpen: boolean;
  onClick: () => void;
}) {
  const ref = useRef<HTMLButtonElement>(null);

  const distance = useTransform(mouseX, (val) => {
    const bounds = ref.current?.getBoundingClientRect();
    if (!bounds) return 999;
    return val - bounds.x - bounds.width / 2;
  });
  const sizeRaw = useTransform(distance, [-140, 0, 140], [48, 78, 48]);
  const size = useSpring(sizeRaw, { stiffness: 200, damping: 20, mass: 0.15 });

  return (
    <div className="flex flex-col items-center">
      <motion.button
        ref={ref}
        onClick={onClick}
        whileTap={{ y: 6, scale: 0.9 }}
        style={{ width: size, height: size }}
        className={`group relative grid place-items-center rounded-2xl bg-gradient-to-br ${item.gradient} text-white shadow-lg shadow-black/40`}
        aria-label={item.label}
      >
        <span className="pointer-events-none absolute -top-8 rounded-md bg-black/70 px-2 py-0.5 text-xs text-white opacity-0 shadow group-hover:opacity-100">
          {item.label}
        </span>
        <span className="[&>svg]:h-1/2 [&>svg]:w-1/2 drop-shadow">{item.icon}</span>
      </motion.button>
      <span
        className={`mt-1 h-1 w-1 rounded-full ${isOpen ? "bg-white/90" : "bg-transparent"}`}
      />
    </div>
  );
}

import { motion } from "framer-motion";
import { useEffect, useRef, useState } from "react";
import { User, ArrowRight } from "lucide-react";

export function LockScreen({ onUnlock }: { onUnlock: () => void }) {
  const [value, setValue] = useState("");
  const [now, setNow] = useState(() => new Date());
  const [unlocking, setUnlocking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  const [error, setError] = useState(false);

  const submit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (unlocking) return;
    if (value.length > 0) {
      setError(true);
      setValue("");
      inputRef.current?.focus();
      return;
    }
    setUnlocking(true);
    setTimeout(onUnlock, 650);
  };

  const time = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false });
  const date = now.toLocaleDateString([], {
    weekday: "long",
    month: "long",
    day: "numeric",
  });

  return (
    <motion.div
      className="fixed inset-0 z-[10001] overflow-hidden text-white"
      initial={{ opacity: 1 }}
      animate={unlocking ? { opacity: 0, scale: 1.05, filter: "blur(20px)" } : { opacity: 1 }}
      transition={{ duration: 0.6, ease: "easeInOut" }}
    >
      <div
        aria-hidden
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(1200px 800px at 20% 10%, oklch(0.55 0.18 300) 0%, transparent 60%)," +
            "radial-gradient(1000px 700px at 85% 20%, oklch(0.6 0.16 260) 0%, transparent 55%)," +
            "radial-gradient(900px 700px at 60% 100%, oklch(0.45 0.15 340) 0%, transparent 60%)," +
            "linear-gradient(180deg, oklch(0.22 0.06 280) 0%, oklch(0.12 0.05 270) 100%)",
        }}
      />
      <div aria-hidden className="absolute inset-0 bg-black/30 backdrop-blur-sm" />

      <div className="relative flex h-full w-full flex-col items-center">
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="mt-16 text-center"
        >
          <div className="text-sm font-medium tracking-wide text-white/80">{date}</div>
          <div className="mt-1 text-8xl font-thin tabular-nums drop-shadow-lg">{time}</div>
        </motion.div>

        <motion.form
          onSubmit={submit}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.25 }}
          className="mt-auto mb-40 flex flex-col items-center"
        >
          <div className="grid h-24 w-24 place-items-center rounded-full bg-gradient-to-br from-sky-400 to-indigo-600 shadow-2xl ring-2 ring-white/30">
            <User size={44} />
          </div>
          <div className="mt-3 text-lg font-medium">Noor Portfolio</div>

          <div className="mt-4 flex items-center gap-2">
            <input
              ref={inputRef}
              type="password"
              value={value}
              onChange={(e) => {
                setValue(e.target.value);
                if (error) setError(false);
              }}
              placeholder="Enter Password"
              className={`w-56 rounded-full border bg-white/10 px-4 py-2 text-center text-sm text-white outline-none backdrop-blur placeholder:text-white/50 focus:border-white/50 ${error ? "border-red-400/70 animate-pulse" : "border-white/20"}`}
              autoComplete="off"
            />
            <button
              type="submit"
              className="grid h-9 w-9 place-items-center rounded-full bg-white/15 text-white transition hover:bg-white/25"
              aria-label="Unlock"
            >
              <ArrowRight size={16} />
            </button>
          </div>
          <div className="mt-3 text-[11px] text-white/60">
            {error ? "Wrong password. Leave it blank and press Enter." : "Press Enter to log in"}
          </div>
        </motion.form>
      </div>
    </motion.div>
  );
}

