import { useEffect, useMemo, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Search, User, FolderKanban, Terminal, Globe, FileText, Mail, BookOpenText } from "lucide-react";
import { useWM } from "./WindowManager";
import type { AppId } from "./types";
import { projects, skills } from "./data";

type Result = {
  id: string;
  label: string;
  category: string;
  appId: AppId;
  payload?: Record<string, unknown>;
  icon: React.ReactNode;
};

export function Spotlight({ open, onClose }: { open: boolean; onClose: () => void }) {
  const wm = useWM();
  const [q, setQ] = useState("");
  const [i, setI] = useState(0);

  useEffect(() => {
    if (open) {
      setQ("");
      setI(0);
    }
  }, [open]);

  const results = useMemo<Result[]>(() => {
    const base: Result[] = [
      { id: "about", label: "About Noor", category: "Application", appId: "about", icon: <User size={16} /> },
      { id: "projects", label: "Projects", category: "Application", appId: "projects", icon: <FolderKanban size={16} /> },
      { id: "terminal", label: "Terminal", category: "Application", appId: "terminal", icon: <Terminal size={16} /> },
      { id: "safari", label: "Safari — Links", category: "Application", appId: "safari", icon: <Globe size={16} /> },
      { id: "resume", label: "Resume.pdf", category: "Document", appId: "resume", icon: <FileText size={16} /> },
      { id: "research", label: "ZKP-Guard — Research Paper", category: "Document", appId: "research", icon: <BookOpenText size={16} /> },
      { id: "mail", label: "Contact Noor", category: "Application", appId: "mail", icon: <Mail size={16} /> },
      ...projects.map<Result>((p) => ({
        id: `proj-${p.id}`,
        label: p.name,
        category: "Project",
        appId: "projects",
        payload: { projectId: p.id },
        icon: <FolderKanban size={16} />,
      })),
      ...Object.entries(skills).flatMap(([group, list]) =>
        list.map<Result>((s) => ({
          id: `skill-${s}`,
          label: s,
          category: `Skill · ${group}`,
          appId: "about",
          icon: <User size={16} />,
        })),
      ),
    ];
    if (!q.trim()) return base.slice(0, 8);
    const needle = q.toLowerCase();
    return base
      .filter((r) => r.label.toLowerCase().includes(needle) || r.category.toLowerCase().includes(needle))
      .slice(0, 8);
  }, [q]);

  useEffect(() => setI(0), [q]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setI((v) => Math.min(v + 1, results.length - 1));
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setI((v) => Math.max(v - 1, 0));
      }
      if (e.key === "Enter") {
        const r = results[i];
        if (r) {
          wm.open(r.appId, { payload: r.payload });
          onClose();
        }
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, results, i, onClose, wm]);

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[10000] flex items-start justify-center bg-black/30 pt-[15vh] backdrop-blur-sm"
          onClick={onClose}
        >
          <motion.div
            initial={{ scale: 0.96, y: -8, opacity: 0 }}
            animate={{ scale: 1, y: 0, opacity: 1 }}
            exit={{ scale: 0.96, opacity: 0 }}
            transition={{ type: "spring", stiffness: 320, damping: 26 }}
            onClick={(e) => e.stopPropagation()}
            className="w-full max-w-xl overflow-hidden rounded-2xl border border-white/15 bg-[oklch(0.22_0.01_260/0.85)] text-white shadow-2xl backdrop-blur-2xl"
          >
            <div className="flex items-center gap-3 border-b border-white/10 px-4 py-3">
              <Search size={18} className="opacity-70" />
              <input
                autoFocus
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder="Spotlight Search"
                className="flex-1 bg-transparent text-lg outline-none placeholder:text-white/40"
              />
              <kbd className="rounded bg-white/10 px-1.5 py-0.5 text-xs text-white/60">ESC</kbd>
            </div>
            <ul className="max-h-80 overflow-y-auto py-1">
              {results.length === 0 && (
                <li className="px-4 py-6 text-center text-sm text-white/50">No results</li>
              )}
              {results.map((r, idx) => (
                <li key={r.id}>
                  <button
                    onMouseEnter={() => setI(idx)}
                    onClick={() => {
                      wm.open(r.appId, { payload: r.payload });
                      onClose();
                    }}
                    className={`flex w-full items-center gap-3 px-4 py-2 text-left text-sm ${
                      i === idx ? "bg-blue-500/70" : "hover:bg-white/5"
                    }`}
                  >
                    <span className="opacity-80">{r.icon}</span>
                    <span className="flex-1 truncate">{r.label}</span>
                    <span className="text-xs text-white/50">{r.category}</span>
                  </button>
                </li>
              ))}
            </ul>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import { AnimatePresence, motion } from "framer-motion";
import { useEffect, useState } from "react";

type Pending = {
  url: string;
  resolve: (ok: boolean) => void;
};

let notify: ((p: Pending | null) => void) | null = null;

export function confirmOpenExternal(url: string): Promise<boolean> {
  return new Promise((resolve) => {
    if (!notify) {
      window.open(url, "_blank", "noopener,noreferrer");
      resolve(true);
      return;
    }
    notify({ url, resolve });
  });
}

export function SystemDialogHost() {
  const [pending, setPending] = useState<Pending | null>(null);

  useEffect(() => {
    notify = setPending;
    return () => {
      notify = null;
    };
  }, []);

  const close = (ok: boolean) => {
    if (pending) {
      pending.resolve(ok);
      if (ok) {
        // Open in the user's real browser tab.
        window.open(pending.url, "_blank", "noopener,noreferrer");
      }
    }
    setPending(null);
  };


  return (
    <AnimatePresence>
      {pending && (
        <motion.div
          className="fixed inset-0 z-[10000] grid place-items-center bg-black/40 backdrop-blur-sm"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
        >
          <motion.div
            initial={{ scale: 0.9, opacity: 0, y: 10 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0 }}
            transition={{ type: "spring", damping: 22, stiffness: 260 }}
            className="w-[380px] overflow-hidden rounded-2xl border border-white/15 bg-zinc-900/90 text-white shadow-2xl backdrop-blur-2xl"
          >
            <div className="px-6 pt-5 text-center">
              <div className="text-[15px] font-semibold">
                "System" would like to open a new tab
              </div>
              <div className="mt-2 line-clamp-2 break-all text-xs text-white/60">
                {pending.url}
              </div>
              <div className="mt-1 text-[11px] text-white/40">
                Opens in your real browser.
              </div>

            </div>
            <div className="mt-5 grid grid-cols-2 border-t border-white/10">
              <button
                onClick={() => close(false)}
                className="border-r border-white/10 py-2.5 text-sm text-white/80 hover:bg-white/5"
              >
                Cancel
              </button>
              <button
                onClick={() => close(true)}
                className="py-2.5 text-sm font-semibold text-sky-400 hover:bg-white/5"
              >
                Allow
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import type { ReactNode } from "react";

export type AppId =
  | "about"
  | "projects"
  | "terminal"
  | "safari"
  | "resume"
  | "mail"
  | "research"
  | "video";

export type WindowState = {
  id: string;
  appId: AppId;
  title: string;
  x: number;
  y: number;
  width: number;
  height: number;
  zIndex: number;
  minimized: boolean;
  maximized: boolean;
  payload?: Record<string, unknown>;
};

export type AppDef = {
  id: AppId;
  name: string;
  icon: ReactNode;
  defaultSize: { width: number; height: number };
  render: (win: WindowState) => ReactNode;
};

import { motion } from "framer-motion";
import { useRef, type ReactNode } from "react";
import { useWM } from "./WindowManager";
import type { WindowState } from "./types";

export function Window({ win, children }: { win: WindowState; children: ReactNode }) {
  const { focus, close, minimize, toggleMaximize, move, focusedId } = useWM();
  const dragStart = useRef({ x: 0, y: 0 });
  const isFocused = focusedId === win.id;

  const style = win.maximized
    ? { top: 28, left: 0, width: "100vw", height: "calc(100vh - 116px)" }
    : { top: win.y, left: win.x, width: win.width, height: win.height };

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.92, y: 20 }}
      animate={{
        opacity: win.minimized ? 0 : 1,
        scale: win.minimized ? 0.3 : 1,
        y: win.minimized ? 400 : 0,
        pointerEvents: win.minimized ? "none" : "auto",
      }}
      exit={{ opacity: 0, scale: 0.9 }}
      transition={{ type: "spring", stiffness: 260, damping: 26 }}
      className="absolute select-none rounded-xl overflow-hidden"
      style={{
        ...style,
        zIndex: win.zIndex,
        boxShadow: isFocused
          ? "0 30px 80px -20px rgba(0,0,0,0.55), 0 8px 24px -6px rgba(0,0,0,0.35), inset 0 0 0 0.5px rgba(255,255,255,0.15)"
          : "0 18px 40px -18px rgba(0,0,0,0.4), inset 0 0 0 0.5px rgba(255,255,255,0.1)",
      }}
      onMouseDown={() => focus(win.id)}
    >
      <div className="flex h-full flex-col bg-[oklch(0.22_0.01_260/0.88)] backdrop-blur-2xl text-white/90">
        {/* Title bar */}
        <div
          className="flex h-8 shrink-0 items-center gap-2 border-b border-white/10 bg-gradient-to-b from-white/10 to-white/5 px-3"
          onMouseDown={(e) => {
            if (win.maximized) return;
            dragStart.current = { x: e.clientX - win.x, y: e.clientY - win.y };
            const onMove = (ev: MouseEvent) => {
              move(
                win.id,
                Math.max(0, ev.clientX - dragStart.current.x),
                Math.max(28, ev.clientY - dragStart.current.y),
              );
            };
            const onUp = () => {
              window.removeEventListener("mousemove", onMove);
              window.removeEventListener("mouseup", onUp);
            };
            window.addEventListener("mousemove", onMove);
            window.addEventListener("mouseup", onUp);
          }}
          onDoubleClick={() => toggleMaximize(win.id)}
        >
          <div className="flex items-center gap-2">
            <button
              aria-label="Close"
              onClick={(e) => {
                e.stopPropagation();
                close(win.id);
              }}
              className="group grid h-3 w-3 place-items-center rounded-full bg-[#ff5f57] hover:brightness-110"
            >
              <span className="hidden text-[8px] text-black/70 group-hover:block">×</span>
            </button>
            <button
              aria-label="Minimize"
              onClick={(e) => {
                e.stopPropagation();
                minimize(win.id);
              }}
              className="group grid h-3 w-3 place-items-center rounded-full bg-[#febc2e] hover:brightness-110"
            >
              <span className="hidden text-[8px] text-black/70 group-hover:block">−</span>
            </button>
            <button
              aria-label="Maximize"
              onClick={(e) => {
